#include <cstdio>
#include <algorithm>
using namespace std;

int mod;
inline int add_mod(int x) {
    return x >= mod ? x - mod : x;
}
inline int sub_mod(int x) {
    return x < 0 ? x + mod : x;
}
int power(int base, int exp) {
    int res=1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return res;
}
struct Pair {
    int a, b;
    Pair(int a=0, int b=0):a(a), b(b) {}
};
Pair operator+(const Pair &x, const Pair &y) {
    return Pair(add_mod(x.a + y.a), add_mod(x.b + y.b));
}
Pair operator*(const Pair &x, const Pair &y) {
    return Pair((long long)x.a * y.a % mod, add_mod((long long)x.a * y.b % mod + (long long)x.b * y.a % mod));
}
int n, m, maxN=100000;
int fact[100005], inv_fact[100005], inv_num[100005];
Pair dp[1005], table[1005][1005];

int sum_func(int x) {
    return (long long)x * (x+1) / 2 % mod;
}

int main() {
    scanf("%d%d%d", &n, &m, &mod);
    fact[0]=inv_fact[0]=1;
    for (int i=1; i<=maxN; i++) {
        fact[i] = (long long)i * fact[i-1] % mod;
        inv_fact[i] = power(fact[i], mod-2);
        inv_num[i] = power(i, mod-2);
    }
    dp[0] = Pair(1,0);
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=i; j++) {
            Pair temp = dp[j-1] * dp[i-j];
            temp.b = add_mod((long long)temp.b * (i+1) % mod + (long long)temp.a * add_mod(sum_func(j-1) + sum_func(i-j)) % mod);
            temp.b = (long long)temp.b * inv_num[i] % mod;
            temp.a = (long long)temp.a * (i+1) % mod * inv_num[i] % mod;
            dp[i] = dp[i] + temp;
        }
    }
    table[0][0] = Pair(1,0);
    for (int i=1; i<=n; i++) {
        for (int j=0; j<=min(i,m); j++) {
            if (i==j) table[i][j]=dp[i];
            for (int k=0; k<j && k<i; k++) {
                table[i][j]=table[i][j]+dp[k]*table[i-k-1][j-k];
            }
        }
    }
    int ans= (long long)table[n][m].b*fact[m]%mod;
    printf("%d\n", ans);
    return 0;
}
